fn main(){let p=std::env::args().nth(1).unwrap();let t=std::fs::read_to_string(&p).unwrap();let f=nodecraft_step::StepFile::parse(&t).unwrap();let b=nodecraft_step::read_topology(&f);for s in b.solids.values(){let shell=b.shells.get(&s.shell).unwrap();let mut names=Vec::new();for fid in &shell.faces{if let Some(face)=b.faces.get(fid){if let Some(surf)=f.entities.get(&face.surface){names.push(surf.name.clone());}}}println!("solid #{} faces {} {:?}",s.id,shell.faces.len(),names);}}
